SELECT analytics_order_facts.channel, COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 3 AND analytics_order_facts.region = 'West' AND analytics_order_facts.customer_segment = 'small_business' GROUP BY analytics_order_facts.channel ORDER BY active_customer_count DESC, analytics_order_facts.channel ASC LIMIT 12
